import numpy as np

def magic_square_test(matrix):
    n = len(matrix)
    magic_sum = n * (n**2 + 1) // 2

    # Check rows
    for row in matrix:
        if sum(row) != magic_sum:
            return False

    # Check columns
    for col in range(n):
        if sum(matrix[row][col] for row in range(n)) != magic_sum:
            return False

    # Check main diagonal
    if sum(matrix[i][i] for i in range(n)) != magic_sum:
        return False

    # Check anti-diagonal
    if sum(matrix[i][n - 1 - i] for i in range(n)) != magic_sum:
        return False

    # Check if all numbers are unique and in the range 1 to n^2
    flat = [num for row in matrix for num in row]
    if sorted(flat) != list(range(1, n**2 + 1)):
        return False

    return True
